    fn write_monolith_plugins(path: &Path, plugin_ids: &[&str]) {
        let mut catalog = serde_json::Map::new();
        for id in plugin_ids {
            catalog.insert(
                (*id).to_string(),
                json!({
                    "name": id,
                    "methods": {
                        "Ping": {
                            "name": "Ping",
                            "args": { "type": "object" },
                            "returns": null,
                            "side_effect": "read",
                            "idempotent": true,
                            "required_capability": null,
                            "subid": format!("obs.service.{}.ping@v1", id)
