/// Call a method on a plugin via its schema-derived D-Bus route.
    pub async fn call_method(
        &self,
        plugin_id: &str,
        method_name: &str,
        json_args: &str,
    ) -> Result<String, SchemaRouterError> {
        // Validation: look up MethodDecl from PluginSchema.methods before dispatch
        let route = self
            .get_route(plugin_id)
            .await
            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;

        // VAL-VALIDATE-005: If PluginSchema.methods is empty, reject ALL method invocations as UnknownMethod
        if route.methods.is_empty() {
            return Err(SchemaRouterError::MethodNotFound {
                plugin_id: plugin_id.to_string(),
                method: method_name.to_string(),
                available: vec![],
            });
        }

        if !route.methods.contains_key(method_name) {
            return Err(SchemaRouterError::MethodNotFound {
                plugin_id: plugin_id.to_string(),
                method: method_name.to_string(),
                available: route.methods.keys().cloned().collect(),
            });
        }

        let method_decl = route.methods.get(method_name).unwrap();

        // VAL-VALIDATE-003: Validate arguments against MethodDecl.args JSON Schema
        if let Some(args_schema) = method_decl.get("args") {
            let args_json: serde_json::Value = serde_json::from_str(json_args)
                .map_err(|e| SchemaRouterError::DbusCallFailed {
                    method: method_name.to_string(),
                    error: format!("Invalid JSON args: {}", e),
                })?;
            let validation_result = jsonschema::validate(&args_json, args_schema);
            match validation_result {
                Ok(_) => (), // Valid, continue
                Err(e) => {
                    // Return InvalidArgs equivalent
                    return Err(SchemaRouterError::DbusCallFailed {
                        method: method_name.to_string(),
                        error: format!("Invalid arguments: JSON does not conform to MethodDecl.args schema: {}", e),
                    });
                }
            }
        }

        let conn = self
            .dbus_connection
            .get()
            .ok_or(SchemaRouterError::DbusUnavailable)?;

        let proxy = Proxy::new(
            conn,
            route.dbus_destination.as_str(),
            route.dbus_path.as_str(),
            route.dbus_interface.as_str(),
        )
        .await
        .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let result: String = proxy
            .call(method_name, &(json_args.to_string(),))
            .await
            .map_err(|e| SchemaRouterError::DbusCallFailed {
                method: method_name.to_string(),
                error: e.to_string(),
            })?;

        Ok(result)
    }

