                    }
                },
                "signals": [
                    {
                        "name": "StatusChanged",
                        "payload": { "type": "object" },
                        "subid": "evt.service.alpha.status-changed@v1"
                    }
                ],
                "properties": { "status": { "type": "string" } }
            },
            "beta": {
                "name": "beta",
                "methods": {
                    "SetKey": {
                        "name": "SetKey",
