                        "returns": null,
                        "side_effect": "mutation",
                        "idempotent": false,
                        "required_capability": "beta.set_key",
                        "subid": "mut.service.beta.set-key@v1"
                    },
                    "GetKey": {
                        "name": "GetKey",
                        "args": { "type": "object", "properties": {} },
                        "returns": { "type": "string" },
                        "side_effect": "read",
                        "idempotent": true,
