        let iface =
            SchemaBackedInterface::with_engine("beta".to_string(), route, Some(engine.clone()));

        // The interface should expose GetStatus method (from route methods)
        assert!(iface.exposes_method("GetStatus"));
        assert!(!iface.exposes_method("UnknownMethod"));

        // Try calling unknown method - should be rejected before dispatch
        let unknown = iface.call("UnknownMethod".to_string(), "{}".to_string()).await;
        assert!(
            matches!(unknown, Err(zbus::fdo::Error::UnknownMethod(_))),
            "unknown method should be rejected as UnknownMethod before SchemaEngine dispatch"
        );
    }

    #[tokio::test]
    async fn unknown_method_rejected_without_mutate() {
        // VAL-VALIDATE-002: Unknown method rejected without calling mutate
        let engine = test_engine();
        let route = dispatch_test_route();
        let iface =
            SchemaBackedInterface::with_engine("beta".to_string(), route, Some(engine.clone()));

        // Ensure the event chain is empty initially
        {
            let chain = engine.event_chain.read().await;
            assert!(chain.events().is_empty(), "event chain should be empty before call");
        }

        // Try calling unknown method
        let unknown = iface.call("UnknownMethod".to_string(), "{}".to_string()).await;
        assert!(
            matches!(unknown, Err(zbus::fdo::Error::UnknownMethod(_))),
            "unknown method should be rejected as UnknownMethod"
        );

        // Event chain should still be empty - mutate should not have been called
        {
            let chain = engine.event_chain.read().await;
            assert!(
                chain.events().is_empty(),
                "SchemaEngine.mutate should not have been called for unknown method"
            );
        }
    }

    #[tokio::test]
    async fn invalid_args_rejected_before_mutate() {
        // VAL-VALIDATE-003: Invalid args rejected before mutate
        let engine = test_engine();
        let route = dispatch_test_route();
        let iface =
            SchemaBackedInterface::with_engine("beta".to_string(), route, Some(engine.clone()));

        // Ensure the event chain is empty initially
        {
            let chain = engine.event_chain.read().await;
            assert!(chain.events().is_empty(), "event chain should be empty before call");
        }

        // Try calling with invalid JSON args (for a method that requires a key)
        let invalid_args = r#"{"wrong_field": 123}""#;
        let result = iface.call("SetKey".to_string(), invalid_args.to_string()).await;
        assert!(
            result.is_err(),
            "invalid args should be rejected before SchemaEngine.dispatch_method_call"
        );

        // Event chain should still be empty - mutate should not have been called
        {
            let chain = engine.event_chain.read().await;
            assert!(
                chain.events().is_empty(),
                "SchemaEngine.mutate should not have been called for invalid args"
            );
        }
    }

    #[tokio::test]
    async fn valid_args_pass_to_mutate() {
        // VAL-VALIDATE-003: Valid args pass through to mutate
        let engine = test_engine();
        let route = dispatch_test_route();
        let iface =
            SchemaBackedInterface::with_engine("beta".to_string(), route, Some(engine.clone()));

        // Ensure the event chain is empty initially
        {
            let chain = engine.event_chain.read().await;
            assert!(chain.events().is_empty(), "event chain should be empty before call");
